css.content:
/* Marquee: two identical tracks translate by one track width. Decorative motion, so it stops for reduced motion. */
.marquee { display: flex; overflow: hidden; }
.marquee-track { display: flex; flex: none; min-width: 100%; align-items: center; justify-content: space-around; animation: marquee-run var(--marquee-duration, 30s) linear infinite; }
.marquee-reverse .marquee-track { animation-direction: reverse; }
.marquee-pause:hover .marquee-track, .marquee-pause:focus-within .marquee-track { animation-play-state: paused; }
@keyframes marquee-run { from { transform: translateX(0); } to { transform: translateX(calc(-100% * var(--dir, 1))); } }
@media (prefers-reduced-motion: reduce) { .marquee { flex-wrap: wrap; } .marquee-track { animation: none; flex-wrap: wrap; } .marquee-track[aria-hidden="true"] { display: none; } }

source.content:
import {forwardRef, type CSSProperties, type HTMLAttributes} from 'react';
import {cx} from '../../utils/cx';

export interface MarqueeProps extends HTMLAttributes<HTMLDivElement> {
  /** Seconds for one full loop. */
  duration?: number;
  /** Scroll to the right instead of the left. Default false. */
  reverse?: boolean;
  /** Stop when the pointer is over it or focus is inside. Default true. */
  pauseOnHover?: boolean;
}

/** Children scroll left (or right with `reverse`). Keep the items short. */
export const Marquee = forwardRef<HTMLDivElement, MarqueeProps>(function Marquee({duration = 30, reverse, pauseOnHover = true, className, style, children, ...rest}, ref) {
  return (
    <div ref={ref} className={cx('marquee', reverse && 'marquee-reverse', pauseOnHover && 'marquee-pause', className)} style={{'--marquee-duration': `${duration}s`, ...style} as CSSProperties} {...rest}>
      <div className="marquee-track">{children}</div>
      <div className="marquee-track" aria-hidden="true">{children}</div>
    </div>
  );
});
